1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
24	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
28	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
33	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
34	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Derives the owner's salutation: the {@code title} followed by a single space and the last
39	     * name (e.g. {@code DR who}), or just the last name when no title is given (absent, empty or
40	     * blank).
41	     */
42	    default String salutation(Owner owner) {
43	        String lastName = owner.getLastName();
44	        String title = owner.getTitle();
45	        if (title == null || title.isBlank()) {
46	            return lastName;
47	        }
48	        return title + " " + lastName;
49	    }
50	
51	    /**
52	     * Formats the stored E.164 {@code telephone} for humans: the {@code '+'} and country code, a
53	     * space, then the national digits grouped in threes (e.g. {@code +61412345678} -&gt;
54	     * {@code +61 412 345 678}). The country code is taken as {@code 61} (Australia) or {@code 1}
55	     * (NANP) when recognised, otherwise a single leading digit. Returns {@code null} when the
56	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164
57	     * number.
58	     */
59	    default String telephoneDisplay(Owner owner) {
60	        String telephone = owner.getTelephone();
61	        if (telephone == null || telephone.isEmpty()) {
62	            return null;
63	        }
64	        if (!telephone.startsWith("+") || !telephone.substring(1).matches("\\d+")) {
65	            return telephone;
66	        }
67	        String digits = telephone.substring(1);
68	        int countryCodeLength;
69	        if (digits.startsWith("61")) {
70	            countryCodeLength = 2;
71	        }
72	        else if (digits.startsWith("1")) {
73	            countryCodeLength = 1;
74	        }
75	        else {
76	            countryCodeLength = 1;
77	        }
78	        String countryCode = digits.substring(0, countryCodeLength);
79	        String national = digits.substring(countryCodeLength);
80	        StringBuilder grouped = new StringBuilder();
81	        for (int i = 0; i < national.length(); i++) {
82	            if (i > 0 && i % 3 == 0) {
83	                grouped.append(' ');
84	            }
85	            grouped.append(national.charAt(i));
86	        }
87	        return "+" + countryCode + (national.isEmpty() ? "" : " " + grouped);
88	    }
89	
90	    /**
91	     * Derives the owner's age band from {@code birthDate} measured against {@code registrationDate}:
92	     * {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older.
93	     * Returns {@code null} when no birthDate is recorded. When the registrationDate is absent (e.g.
94	     * legacy records) the current date is used as the reference point.
95	     */
96	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
97	        java.time.LocalDate birthDate = owner.getBirthDate();
98	        if (birthDate == null) {
99	            return null;
100	        }
101	        java.time.LocalDate reference = owner.getRegistrationDate() != null
102	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
103	        int age = java.time.Period.between(birthDate, reference).getYears();
104	        if (age < 18) {
105	            return OwnerDto.AgeBandEnum.MINOR;
106	        }
107	        if (age < 65) {
108	            return OwnerDto.AgeBandEnum.ADULT;
109	        }
110	        return OwnerDto.AgeBandEnum.SENIOR;
111	    }
112	
113	    /**
114	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is
115	     * present, otherwise {@code PHONE}.
116	     */
117	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
118	        String email = owner.getEmail();
119	        if (email != null && !email.isEmpty()) {
120	            return OwnerDto.ContactPreferenceEnum.EMAIL;
121	        }
122	        return OwnerDto.ContactPreferenceEnum.PHONE;
123	    }
124	
125	    /**
126	     * Derives the owner's locality (region) from the region-and-hash identity: it is the
127	     * {@code <REGION>} segment of the customerCode ({@code <REGION>-<HASH8>}), i.e. the region
128	     * derived from the postcode at create time. When the customerCode is absent or malformed
129	     * (e.g. legacy records), it falls back to the postcode range and then the fixed city-to-region
130	     * table, returning {@code UNKNOWN} when neither source resolves.
131	     */
132	    default String locality(Owner owner) {
133	        String code = owner.getCustomerCode();
134	        if (code != null) {
135	            int dash = code.indexOf('-');
136	            if (dash > 0) {
137	                return code.substring(0, dash);
138	            }
139	        }
140	        String region = regionFromPostcode(owner);
141	        if (region != null) {
142	            return region;
143	        }
144	        return cityRegion(owner);
145	    }
146	
147	    /**
148	     * Derives the owner's IANA timezone from the {@link #locality(Owner) locality/region}
149	     * via the fixed region-to-timezone table (NSW-&gt;Australia/Sydney,
150	     * VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane). Returns {@code null}
151	     * when the region is not in the table.
152	     */
153	    default String timezone(Owner owner) {
154	        String region = locality(owner);
155	        switch (region) {
156	            case "NSW":
157	                return "Australia/Sydney";
158	            case "VIC":
159	                return "Australia/Melbourne";
160	            case "QLD":
161	                return "Australia/Brisbane";
162	            default:
163	                return null;
164	        }
165	    }
166	
167	    /**
168	     * Maps the owner's city to its region via the fixed city-to-region table
169	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). Returns {@code UNKNOWN}
170	     * when the city is absent or not in the table.
171	     */
172	    default String cityRegion(Owner owner) {
173	        String city = owner.getCity();
174	        if (city == null) {
175	            return "UNKNOWN";
176	        }
177	        switch (city) {
178	            case "Sydney":
179	                return "NSW";
180	            case "Melbourne":
181	                return "VIC";
182	            case "Brisbane":
183	                return "QLD";
184	            default:
185	                return "UNKNOWN";
186	        }
187	    }
188	
189	    /**
190	     * Resolves the region from the owner's 4-digit postcode range, or {@code null}
191	     * when the postcode is absent, malformed, or in no known range.
192	     */
193	    default String regionFromPostcode(Owner owner) {
194	        String postcode = owner.getPostcode();
195	        if (postcode == null) {
196	            return null;
197	        }
198	        int code;
199	        try {
200	            code = Integer.parseInt(postcode.trim());
201	        }
202	        catch (NumberFormatException ex) {
203	            return null;
204	        }
205	        if (code >= 2000 && code <= 2099) {
206	            return "NSW";
207	        }
208	        if (code >= 3000 && code <= 3099) {
209	            return "VIC";
210	        }
211	        if (code >= 4000 && code <= 4099) {
212	            return "QLD";
213	        }
214	        return null;
215	    }
216	
217	    /**
218	     * Returns the owner's membership points. The score starts at 0 and gains 2 when an email is
219	     * present, 1 when {@code namesakeCount} is 0, 2 when the household has 3 or more members, and 3
220	     * when tenure exceeds one elapsed fiscal year.
221	     */
222	    default Integer membershipPoints(Owner owner) {
223	        int points = 0;
224	        String email = owner.getEmail();
225	        if (email != null && !email.isEmpty()) {
226	            points += 2;
227	        }
228	        Integer namesakeCount = owner.getNamesakeCount();
229	        if (namesakeCount != null && namesakeCount == 0) {
230	            points += 1;
231	        }
232	        Integer householdSize = owner.getHouseholdSize();
233	        if (householdSize != null && householdSize >= 3) {
234	            points += 2;
235	        }
236	        if (tenureFiscalYears(owner) > 1) {
237	            points += 3;
238	        }
239	        return points;
240	    }
241	
242	    /**
243	     * Returns the owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
244	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or
245	     * more points. The derived level is then capped by {@link Owner#getMembershipLevelCap()} when
246	     * present, so a new owner's level cannot exceed one above the highest level in their household.
247	     */
248	    default Integer membershipLevel(Owner owner) {
249	        int points = membershipPoints(owner);
250	        int level;
251	        if (points <= 1) {
252	            level = 1;
253	        }
254	        else if (points <= 3) {
255	            level = 2;
256	        }
257	        else if (points <= 5) {
258	            level = 3;
259	        }
260	        else {
261	            level = 4;
262	        }
263	        Integer cap = owner.getMembershipLevelCap();
264	        if (cap != null && level > cap) {
265	            level = cap;
266	        }
267	        return level;
268	    }
269	
270	    /**
271	     * The owner's tenure in whole elapsed fiscal years: the number of fiscal-year boundaries
272	     * (1 July) crossed between {@code registrationDate} and the current date. A newly created
273	     * owner (registered in the current fiscal year) has zero tenure, and a missing
274	     * registrationDate (e.g. legacy records) is likewise treated as zero.
275	     */
276	    default long tenureFiscalYears(Owner owner) {
277	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
278	        if (registrationDate == null) {
279	            return 0;
280	        }
281	        long years = fiscalYearOf(java.time.LocalDate.now()) - fiscalYearOf(registrationDate);
282	        return Math.max(years, 0);
283	    }
284	
285	    /**
286	     * The fiscal year (a four-digit calendar year) that the given date falls in. The fiscal year
287	     * starts on 1 July and is identified by the calendar year in which it ends, so a date on or
288	     * after 1 July belongs to the fiscal year of the following calendar year.
289	     */
290	    default int fiscalYearOf(java.time.LocalDate date) {
291	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
292	    }
293	
294	    /**
295	     * The owner's fiscal year, formatted 'FY&lt;YY&gt;' where YY is the last two digits of the
296	     * fiscal year of the {@code registrationDate} (which is stored business-day-adjusted). The
297	     * fiscal year starts on 1 July. Returns {@code null} when no registrationDate is recorded.
298	     */
299	    default String fiscalYear(Owner owner) {
300	        if (owner.getRegistrationDate() == null) {
301	            return null;
302	        }
303	        return "FY" + String.format("%02d", fiscalYearOf(owner.getRegistrationDate()) % 100);
304	    }
305	
306	    /**
307	     * Builds the owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;'
308	     * where YY is the last two digits of the fiscal year of the (business-day-adjusted)
309	     * registrationDate. Returns {@code null} when either source field is absent.
310	     */
311	    default String membershipNumber(Owner owner) {
312	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
313	            return null;
314	        }
315	        return owner.getCustomerCode() + "-M"
316	            + String.format("%02d", fiscalYearOf(owner.getRegistrationDate()) % 100);
317	    }
